import db from '@/lib/firestore';

export async function POST(req) {
    try {
        const { quotationId } = await req.json();

        if (!quotationId) {
            return Response.json({ error: 'Quotation ID is required' }, { status: 400 });
        }

        // Generate professional code: COT-YYYY-NNNN
        const currentYear = new Date().getFullYear();
        const yearStart = new Date(currentYear, 0, 1).toISOString();
        const yearEnd = new Date(currentYear, 11, 31, 23, 59, 59).toISOString();

        // Count only published quotations from current year
        const snapshot = await db.collection('quotations')
            .where('isPublished', '==', true)
            .where('createdAt', '>=', yearStart)
            .where('createdAt', '<=', yearEnd)
            .get();

        const countThisYear = snapshot.size;
        const nextNumber = countThisYear + 1;
        const code = `COT-${currentYear}-${String(nextNumber).padStart(4, '0')}`;

        // Update quotation to published with code
        await db.collection('quotations').doc(quotationId).update({
            code,
            isPublished: true,
            status: 'published',
            updatedAt: new Date().toISOString()
        });

        return Response.json({ success: true, code });
    } catch (error) {
        console.error(error);
        return Response.json({ error: 'Failed to publish quotation' }, { status: 500 });
    }
}
